import{_ as i,W as l,s as o,u as d,ah as r,I as t,w as s,Z as e,A as p}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const k=JSON.parse('{"title":"在 Linux 上复制和重命名文件 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上复制和重命名文件 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"在 Linux 上复制和重命名文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上复制和重命名文件 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180529 Copying and renaming files on Linux","title":"在 Linux 上复制和重命名文件","tag":"201806"},"relativePath":"201806/20180529 Copying and renaming files on Linux.md","filePath":"[post].md"}'),c={name:"201806/20180529 Copying and renaming files on Linux.md"};function u(g,n,m,h,v,b){const a=l("Link");return d(),o("div",null,[n[20]||(n[20]=r(`<h1 id="在-linux-上复制和重命名文件" tabindex="-1">在 Linux 上复制和重命名文件 <a class="header-anchor" href="#在-linux-上复制和重命名文件" aria-label="Permalink to 在 Linux 上复制和重命名文件">​</a></h1><blockquote><p>cp 和 mv 之外，在 Linux 上有更多的复制和重命名文件的命令。试试这些命令或许会惊艳到你，并能节省一些时间。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/05/trees-100759415-large.jpg" alt=""></p><p>Linux 用户数十年来一直在使用简单的 <code>cp</code> 和 <code>mv</code> 命令来复制和重命名文件。这些命令是我们大多数人首先学到的，每天可能有数百万人在使用它们。但是还有其他技术、方便的方法和另外的命令，这些提供了一些独特的选项。</p><p>首先，我们来思考为什么你想要复制一个文件。你可能需要在另一个位置使用同一个文件，或者因为你要编辑该文件而需要一个副本，并且希望确保备有便利的备份以防万一需要恢复原始文件。这样做的显而易见的方式是使用像 <code>cp myfile myfile-orig</code> 这样的命令。</p><p>但是，如果你想复制大量的文件，那么这个策略可能就会变得很老。更好的选择是：</p><ul><li>在开始编辑之前，使用 <code>tar</code> 创建所有要备份的文件的存档。</li><li>使用 <code>for</code> 循环来使备份副本更容易。</li></ul><p>使用 <code>tar</code> 的方式很简单。对于当前目录中的所有文件，你可以使用如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tar cf myfiles.tar *</span></span></code></pre></div><p>对于一组可以用模式标识的文件，可以使用如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tar cf myfiles.tar *.txt</span></span></code></pre></div><p>在每种情况下，最终都会生成一个 <code>myfiles.tar</code> 文件，其中包含目录中的所有文件或扩展名为 .txt 的所有文件。</p><p>一个简单的循环将允许你使用修改后的名称来制作备份副本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ for file in *</span></span>
<span class="line"><span>&gt; do</span></span>
<span class="line"><span>&gt; cp $file $file-orig</span></span>
<span class="line"><span>&gt; done</span></span></code></pre></div><p>当你备份单个文件并且该文件恰好有一个长名称时，可以依靠使用 <code>tab</code> 来补全文件名（在输入足够的字母以便唯一标识该文件后点击 <code>Tab</code> 键）并使用像这样的语法将 <code>-orig</code> 附加到副本的名字后。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cp file-with-a-very-long-name{,-orig}</span></span></code></pre></div><p>然后你有一个 <code>file-with-a-very-long-name</code> 和一个 <code>file-with-a-very-long-name-orig</code>。</p><h3 id="在-linux-上重命名文件" tabindex="-1">在 Linux 上重命名文件 <a class="header-anchor" href="#在-linux-上重命名文件" aria-label="Permalink to 在 Linux 上重命名文件">​</a></h3><p>重命名文件的传统方法是使用 <code>mv</code> 命令。该命令将文件移动到不同的目录，或原地更改其名称，或者同时执行这两个操作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mv myfile /tmp</span></span>
<span class="line"><span>$ mv myfile notmyfile</span></span>
<span class="line"><span>$ mv myfile /tmp/notmyfile</span></span></code></pre></div><p>但我们也有 <code>rename</code> 命令来做重命名。使用 <code>rename</code> 命令的窍门是习惯它的语法，但是如果你了解一些 Perl，你可能发现它并不棘手。</p><p>有个非常有用的例子。假设你想重新命名一个目录中的文件，将所有的大写字母替换为小写字母。一般来说，你在 Unix 或 Linux 系统上找不到大量大写字母的文件，但你可以有。这里有一个简单的方法来重命名它们，而不必为它们中的每一个使用 <code>mv</code> 命令。 <code>/A-Z/a-z/</code> 告诉 <code>rename</code> 命令将范围 <code>A-Z</code> 中的任何字母更改为 <code>a-z</code> 中的相应字母。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Agenda Group.JPG MyFile</span></span>
<span class="line"><span>$ rename &#39;y/A-Z/a-z/&#39; *</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>agenda group.jpg myfile</span></span></code></pre></div><p>你也可以使用 <code>rename</code> 来删除文件扩展名。也许你厌倦了看到带有 .txt 扩展名的文本文件。简单删除这些扩展名 —— 用一个命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>agenda.txt notes.txt weekly.txt</span></span>
<span class="line"><span>$ rename &#39;s/.txt//&#39; *</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>agenda notes weekly</span></span></code></pre></div><p>现在让我们想象一下，你改变了心意，并希望把这些扩展名改回来。没问题。只需修改命令。窍门是理解第一个斜杠前的 <code>s</code> 意味着“替代”。前两个斜线之间的内容是我们想要改变的东西，第二个斜线和第三个斜线之间是改变后的东西。所以，<code>$</code> 表示文件名的结尾，我们将它改为 <code>.txt</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>agenda notes weekly</span></span>
<span class="line"><span>$ rename &#39;s/$/.txt/&#39; *</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>agenda.txt notes.txt weekly.txt</span></span></code></pre></div><p>你也可以更改文件名的其他部分。牢记 <code>s/旧内容/新内容/</code> 规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>draft-minutes-2018-03 draft-minutes-2018-04 draft-minutes-2018-05</span></span>
<span class="line"><span>$ rename &#39;s/draft/approved/&#39; *minutes*</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>approved-minutes-2018-03 approved-minutes-2018-04 approved-minutes-2018-05</span></span></code></pre></div><p>在上面的例子中注意到，当我们在 <code>s/old/new/</code> 中使用 <code>s</code> 时，我们用另一个名称替换名称的一部分。当我们使用 <code>y</code> 时，我们就是直译（将字符从一个范围替换为另一个范围）。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>现在有很多复制和重命名文件的方法。我希望其中的一些会让你在使用命令行时更愉快。</p>`,32)),t("p",null,[n[2]||(n[2]=s("在 ")),e(a,{href:"https://www.facebook.com/NetworkWorld/"},{default:p(()=>n[0]||(n[0]=[s("Facebook")])),_:1}),n[3]||(n[3]=s(" 和 ")),e(a,{href:"https://www.linkedin.com/company/network-world"},{default:p(()=>n[1]||(n[1]=[s("LinkedIn")])),_:1}),n[4]||(n[4]=s(" 上加入 Network World 社区来对热门主题评论。"))]),n[21]||(n[21]=t("hr",null,null,-1)),t("p",null,[n[6]||(n[6]=s("via: ")),e(a,{href:"https://www.networkworld.com/article/3276349/linux/copying-and-renaming-files-on-linux.html"},{default:p(()=>n[5]||(n[5]=[s("https://www.networkworld.com/article/3276349/linux/copying-and-renaming-files-on-linux.html")])),_:1})]),t("p",null,[n[11]||(n[11]=s("作者：")),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>n[7]||(n[7]=[s("Sandra Henry-Stocker")])),_:1}),n[12]||(n[12]=s(" 选题：")),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>n[8]||(n[8]=[s("lujun9972")])),_:1}),n[13]||(n[13]=s(" 译者：")),e(a,{href:"https://github.com/geekpi"},{default:p(()=>n[9]||(n[9]=[s("geekpi")])),_:1}),n[14]||(n[14]=s(" 校对：")),e(a,{href:"https://github.com/wxy"},{default:p(()=>n[10]||(n[10]=[s("wxy")])),_:1})]),t("p",null,[n[17]||(n[17]=s("本文由 ")),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>n[15]||(n[15]=[s("LCTT")])),_:1}),n[18]||(n[18]=s(" 原创编译，")),e(a,{href:"https://linux.cn/"},{default:p(()=>n[16]||(n[16]=[s("Linux中国")])),_:1}),n[19]||(n[19]=s(" 荣誉推出"))])])}const y=i(c,[["render",u]]);export{k as __pageData,y as default};
